#nullable enable

using System.Collections.Immutable;
using System.Linq;
using Microsoft.CodeAnalysis;

namespace Haitch.Roslyn.Semantics;

/// <summary>
/// Reads the shapes of a type a generator asks about, so it does not compare special types, walk
/// base types and interfaces or filter an enum's members by hand.
/// </summary>
internal static class TypeSymbolExtensions
{
    /// <summary>
    /// Finds the <c>T</c> of a <see cref="System.Nullable{T}"/>, whether written as <c>Nullable&lt;T&gt;</c>
    /// or <c>T?</c>; null for any other type, including a reference type annotated with <c>?</c> and
    /// the unconstructed <see cref="System.Nullable{T}"/> definition.
    /// </summary>
    /// <param name="type">The type to read.</param>
    /// <returns>The underlying value type, such as the enum of a nullable enum.</returns>
    public static ITypeSymbol? NullableUnderlying(this ITypeSymbol type)
    {
        return type is INamedTypeSymbol { OriginalDefinition.SpecialType: SpecialType.System_Nullable_T } nullable
            && IsConstructed(nullable)
            ? nullable.TypeArguments[0]
            : null;
    }

    // A definition's type arguments are its own type parameters, which no value is declared with.
    private static bool IsConstructed(INamedTypeSymbol type)
    {
        return !SymbolEqualityComparer.Default.Equals(type, type.OriginalDefinition);
    }

    /// <summary>
    /// Tells whether <paramref name="type"/> is the interface named <paramref name="metadataName"/>
    /// or implements it, directly, through a base type or through another interface, matching a
    /// constructed generic interface by its definition.
    /// </summary>
    /// <param name="type">The type to read.</param>
    /// <param name="metadataName">The interface's metadata name, such as <c>System.Collections.Generic.ICollection`1</c>.</param>
    /// <returns>True when the type is or implements the interface.</returns>
    public static bool IsOrImplements(this ITypeSymbol type, string metadataName)
    {
        return type is INamedTypeSymbol named && IsNamed(named, metadataName)
            || type.AllInterfaces.Any(@interface => IsNamed(@interface, metadataName));
    }

    public static bool IsOrImplements(
        this ITypeSymbol type,
        string metadataName,
        ITypeSymbol typeArgument)
    {
        if (type is INamedTypeSymbol named && IsNamed(named, metadataName, typeArgument))
        {
            return true;
        }

        foreach (var @interface in type.AllInterfaces)
        {
            if (IsNamed(@interface, metadataName, typeArgument))
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsNamed(INamedTypeSymbol type, string metadataName, ITypeSymbol typeArgument)
    {
        return IsNamed(type, metadataName)
            && type.TypeArguments.Length == 1
            && SymbolEqualityComparer.Default.Equals(type.TypeArguments[0], typeArgument);
    }

    /// <summary>
    /// Finds the first base class of <paramref name="type"/>, the type itself excluded, whose
    /// definition is named <paramref name="metadataName"/>; null when the type does not derive from it.
    /// </summary>
    /// <param name="type">The type to read.</param>
    /// <param name="metadataName">The base class's metadata name, such as <c>Ns.Validator`1</c>.</param>
    /// <returns>The base class as the type declares it, so a generic base's type arguments are readable.</returns>
    public static INamedTypeSymbol? FindBase(this ITypeSymbol type, string metadataName)
    {
        for (var baseType = type.BaseType; baseType is not null; baseType = baseType.BaseType)
        {
            if (IsNamed(baseType, metadataName))
            {
                return baseType;
            }
        }

        return null;
    }

    /// <summary>
    /// Lists the constant fields <paramref name="type"/> declares when it is an enum, in declaration
    /// order and including aliases that share a value; empty for any other type.
    /// </summary>
    /// <param name="type">The type to read.</param>
    /// <returns>The enum's members, each with its name and constant value.</returns>
    public static ImmutableArray<IFieldSymbol> EnumMembers(this INamedTypeSymbol type)
    {
        return type.TypeKind == TypeKind.Enum
            ? type.GetMembers().OfType<IFieldSymbol>().ToImmutableArray()
            : ImmutableArray<IFieldSymbol>.Empty;
    }

    private static bool IsNamed(INamedTypeSymbol type, string metadataName)
    {
        return type.OriginalDefinition.FullMetadataName() == metadataName;
    }
}
